//! Oracle comparison: the LSST FrameSet's transforms against the C library.
//!
//! `lsst_oracle/cases.rs` is generated by `tools/oracle_fixtures/lsst_probe.c`
//! from `fixtures/wcsconv/inputs/lsst.ast`: the forward transform of ten pixel
//! positions, the same through the FrameSet as read and through its simplified
//! form, and the inverse transform of those outputs through each. The inverse
//! runs PolyMap's iterative inverse, which stops at the Mapping's TolInv, so
//! the two inverses differ slightly from each other in C and are compared
//! separately.

use starlink_ast::coords::PointSet;
use starlink_ast::from_native_string;
use starlink_ast::mappings::Mapping;

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "lsst_oracle/cases.rs"]
mod cases;

use cases::{C_FORWARD, C_INVERSE_OF_FORWARD, C_SIMPLIFIED_INVERSE_OF_FORWARD, NPTS};

fn input_points() -> PointSet {
    PointSet::from_rows(
        (0..NPTS)
            .map(|i| vec![100.0 + i as f64 * 0.01, 200.0 + i as f64 * 0.005])
            .collect::<Vec<_>>(),
    )
}

fn load_lsst() -> Box<dyn Mapping> {
    let text = std::fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/wcsconv/inputs/lsst.ast"
    ))
    .unwrap();
    from_native_string(&text).unwrap().into_mapping().unwrap()
}

fn points(pairs: &[(f64, f64); NPTS]) -> PointSet {
    PointSet::from_rows(pairs.iter().map(|&(x, y)| vec![x, y]).collect::<Vec<_>>())
}

fn flatten(ps: &PointSet) -> Vec<f64> {
    (0..ps.npoint())
        .flat_map(|i| ps.point(i).to_vec())
        .collect()
}

fn flatten_pairs(pairs: &[(f64, f64); NPTS]) -> Vec<f64> {
    pairs.iter().flat_map(|&(x, y)| [x, y]).collect()
}

/// Comparisons that, off the platform the C values were captured on, differ
/// from C by more than libm rounding, with the most measured. The inverse
/// runs PolyMap's iterative inverse, which stops once a step is below the
/// Mapping's TolInv (1e-7 pixel), so a last-bit difference in another libm's
/// sines, cosines and arctangents moves where it stops: up to 4.5e-10 pixel
/// on Linux x86-64 (CI, 2026-10-28). On the capture platform every
/// comparison is exact.
const OFF_PLATFORM_DRIFT_LICENSED: &[(&str, f64)] = &[
    ("original inverse", 4.5e-10),
    ("simplified inverse", 4.5e-10),
];

/// Compare `got` with C's `want`: exactly on the capture platform, and
/// elsewhere within the measured drift if `what` is in
/// [`OFF_PLATFORM_DRIFT_LICENSED`] or within libm rounding if not.
fn assert_matches_c(got: &[f64], want: &[f64], what: &str) {
    match OFF_PLATFORM_DRIFT_LICENSED
        .iter()
        .find(|(name, _)| *name == what)
    {
        Some(&(_, atol)) if !crate::common::on_capture_platform() => assert!(
            got.len() == want.len() && got.iter().zip(want).all(|(g, w)| (g - w).abs() <= atol),
            "{what}: got {got:?}, C gives {want:?}"
        ),
        _ => crate::common::assert_c_values(got, want, what),
    }
}

#[test]
fn lsst_original_forward_matches_c() {
    let out = load_lsst().transform(&input_points(), true).unwrap();
    assert_matches_c(
        &flatten(&out),
        &flatten_pairs(&C_FORWARD),
        "original forward",
    );
}

#[test]
fn lsst_simplified_forward_matches_c() {
    let out = load_lsst()
        .simplify()
        .unwrap()
        .transform(&input_points(), true)
        .unwrap();
    assert_matches_c(
        &flatten(&out),
        &flatten_pairs(&C_FORWARD),
        "simplified forward",
    );
}

#[test]
fn lsst_original_inverse_matches_c() {
    let inv = load_lsst().transform(&points(&C_FORWARD), false).unwrap();
    assert_matches_c(
        &flatten(&inv),
        &flatten_pairs(&C_INVERSE_OF_FORWARD),
        "original inverse",
    );
}

#[test]
fn lsst_simplified_inverse_matches_c() {
    let inv = load_lsst()
        .simplify()
        .unwrap()
        .transform(&points(&C_FORWARD), false)
        .unwrap();
    assert_matches_c(
        &flatten(&inv),
        &flatten_pairs(&C_SIMPLIFIED_INVERSE_OF_FORWARD),
        "simplified inverse",
    );
}

#[test]
fn lsst_inverse_round_trip() {
    let mapping = load_lsst();
    let pts = input_points();
    let fwd = mapping.transform(&pts, true).unwrap();
    let inv = mapping.transform(&fwd, false).unwrap();

    for i in 0..NPTS {
        let ox = pts.point(i)[0];
        let oy = pts.point(i)[1];
        let rx = inv.point(i)[0];
        let ry = inv.point(i)[1];
        // C library achieves ~1e-9 round-trip on this fixture; match that.
        assert!(
            (rx - ox).abs() < 1e-6,
            "pt {i} x round-trip: orig={ox}, recovered={rx}"
        );
        assert!(
            (ry - oy).abs() < 1e-6,
            "pt {i} y round-trip: orig={oy}, recovered={ry}"
        );
    }
}
